import{z as l,x as i,o as e,c as A,q as s,j as t,D as E,d as o,s as n,S as r}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"失业的存量-流量与贝弗里奇","description":"","frontmatter":{"title":"失业的存量-流量与贝弗里奇","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/unemployment-stock-flow.md","filePath":"econ/unemployment-stock-flow.md","lastUpdated":1791413859000}'),p={name:"econ/unemployment-stock-flow.md"};function u(d,a,f,m,D,c){const B=i("Mermaid");return e(),A("div",null,[a[2]||(a[2]=s('<h1 id="失业的存量-流量与贝弗里奇" tabindex="-1">失业的存量-流量与贝弗里奇 <a class="header-anchor" href="#失业的存量-流量与贝弗里奇" aria-label="Permalink to &quot;失业的存量-流量与贝弗里奇&quot;">​</a></h1><div class="epigraph"><p>失业不是一群静止的人，而是一池有人不断落水、有人不断爬岸的水；水位的涨落要先问两个阀门，哪一个在动。</p><footer>—— 据 Hall, Job Loss, Job Finding, and Unemployment over the Past Fifty Years, NBER Macro Annual 2005；Shimer, Reassessing the Ins and Outs of Unemployment, RED 2012 整理</footer></div><p><a href="/econ/superstar-labor">上一课</a>用 Rosen 1981 的超级明星经济收束「谁赚得多」：赢者通拿的市场里，市场规模与技术放大把微小的能力差写成指数级的收入差，工资分布的右尾由赢家吃掉。本课转入新单元「失业、搜寻与制度」的起点：右尾之外还有整块存量——没被任何工资曲线吸进去的失业人口。宏观主干已有<a href="/econ/beveridge-curve">贝弗里奇曲线</a>的 U–V 观测与<a href="/econ/search-matching-dmp">搜寻匹配</a>的均衡模型；分工是：DMP 课讲匹配函数如何把 \\((u,v)\\) 收成均衡，本课做实证流量核算——把失业率当成水位的会计，从分离率与入职率的月度流量出发，回答「这一轮失业上行，是落水的人多了，还是爬岸的人少了」。后课的搜寻与制度讨论默认已读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>U–V 图给了两个存量的对照，没给时间。同一个 \\(u=7\\%\\)，可以是大量裁员又快速招回的经济，也可以是缓慢流失、缓慢回补的经济，政策含义完全不同。缺口是把静态对照换成流量账：失业的变动分解为流入（分离）与流出（入职），即所谓 ins 与 outs 的分解。</p><p>做法：记失业率为 \\(u\\)，每月分离率 \\(s\\)（就业者转入失业的比例）与入职率 \\(f\\)（失业者转入就业的比例），流量恒等式近似为</p> \\[u_{t+1}-u_t \\;=\\; s_t\\,(1-u_t)\\;-\\;f_t\\,u_t . \\]<p>令左端为零，稳态是 \\(u^{*}=\\dfrac{s}{s+f}\\)。这个式子是本课的全部会计：要问失业为什么变，就把 \\(s\\) 与 \\(f\\) 各自的路径摆出来。</p>',8)),(e(),t(r,null,{default:E(()=>[n(B,{id:"mermaid-20",class:"mermaid",graph:"flowchart%20TD%0A%20%20SEP%5B%22%E5%88%86%E7%A6%BB%E7%8E%87%20s%EF%BC%9A%E5%B0%B1%E4%B8%9A%20%E2%86%92%20%E5%A4%B1%E4%B8%9A%22%5D%20--%3E%20D%5B%22%CE%94u%20%3D%20s(1%E2%88%92u)%20%E2%88%92%20f%C2%B7u%22%5D%0A%20%20FIND%5B%22%E5%85%A5%E8%81%8C%E7%8E%87%20f%EF%BC%9A%E5%A4%B1%E4%B8%9A%20%E2%86%92%20%E5%B0%B1%E4%B8%9A%22%5D%20--%3E%20D%0A%20%20D%20--%3E%20SS%5B%22%E7%A8%B3%E6%80%81%20u*%20%3D%20s%20%2F%20(s%20%2B%20f)%22%5D%0A%20%20D%20--%3E%20Q%5B%22%E5%88%86%E8%A7%A3%EF%BC%9Ains%20%E8%BF%98%E6%98%AF%20outs%20%E5%9C%A8%E5%8A%A8%22%5D%0A%20%20Q%20--%3E%20USE%5B%22%E8%AF%BB%E8%B4%9D%E5%BC%97%E9%87%8C%E5%A5%87%EF%BC%9A%E6%B2%BF%E6%9B%B2%E7%BA%BF%E6%88%96%E5%A4%96%E7%A7%BB%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s('<p><span class="marginnote">用美国月度量级做心算：\\(s\\approx 2\\%\\)、\\(f\\approx 20\\%\\) 时 \\(u^{*}\\approx 9\\%\\)；\\(f\\) 减半而 \\(s\\) 不变，稳态推到约 \\(17\\%\\)。换句话说，入职率腰斩对水位的推动，不亚于分离率翻倍。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分解的口径有三条纪律。第一，两态简化（就业、失业）会漏掉「退出劳动力」这个第三态：泄气工人退出后，\\(u\\) 的分母缩小，水位显得比就业损失好看——<a href="/econ/labor-participation">参与课</a>的分母警告在流量上仍然有效。第二，毛流量数据噪声大，入职率要从失业退出的转阵概率反推，并剔除「直接退出劳动力」的部分，否则 \\(f\\) 被低估。第三，临时裁员与召回预期会把 \\(s\\) 的高频尖峰读成破坏潮，实际是等待召回。</p><p>Hall 对战后五十年的核算与 Shimer 的再评估给出一致的定量结论：美国周期里 \\(u\\) 的波动主要由 \\(f\\) 的下降驱动，\\(s\\) 相对平稳；大衰退中 Elsby–Hobijn–Şahin 发现分离率也显著抬升，是例外而非通则。这套 ins/outs 的分法接回<a href="/econ/beveridge-curve">贝弗里奇曲线</a>：\\(f\\) 下降是沿曲线向高 \\(u\\)、低 \\(v\\) 走；\\(s\\) 上升或匹配效率崩坏才是曲线外移——流量账给 U–V 图装上了时钟。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么分解错了会错在政策上：若把「分离率上升的衰退」误读成「招聘变慢的衰退」，工具会去补贴招聘广告与匹配，而真实的阀门是岗位破坏与临时解雇，该稳的是存量就业。若把「入职率下降」误读成「工人不肯工作」，又会漏掉岗位创造侧的收缩——\\(f\\) 是接触率与接受率的乘积，市场侧与工人侧都要拆开读。</p><p>长期失业的构成是另一层会计：大多数失业期间很短，但某一时点的失业存量集中在少数长期失业者身上——「平均失业期」由短期间拖动，存量却堆积在长尾。只看月度流量健康，会漏掉长尾的技能折旧与再就业难度上升。这也解释了为什么 DMP 课把 \\(u^{*}\\) 写成摩擦均衡：稳态公式的 \\(s\\) 与 \\(f\\) 都是行为参数，制度（解雇成本、失业保险、招聘渠道）改写它们，是本单元后课的对象。</p><p><span class="marginnote">Fujita–Ramey 2009 与 Hall 2005 都用流量方差分解确认：入职率的周期方差贡献远大于分离率。这个「outs 主导」不是定理，是美国月度数据的量级事实，跨国会变。</span></p>',8)),(e(),t(r,null,{default:E(()=>[n(B,{id:"mermaid-45",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E5%A4%B1%E4%B8%9A%E7%8E%87%E4%B8%8A%E8%A1%8C%22%5D%20--%3E%20DQ%7B%22%E5%85%88%E6%8B%86%20ins%20%E4%B8%8E%20outs%22%7D%0A%20%20DQ%20--%20%22f%20%E4%B8%8B%E9%99%8D%E4%B8%BB%E5%AF%BC%22%20--%3E%20BV1%5B%22%E6%B2%BF%E8%B4%9D%E5%BC%97%E9%87%8C%E5%A5%87%E6%9B%B2%E7%BA%BF%EF%BC%9Au%20%E5%8D%87%E3%80%81v%20%E9%99%8D%22%5D%0A%20%20DQ%20--%20%22s%20%E4%B8%8A%E5%8D%87%E4%B8%BB%E5%AF%BC%22%20--%3E%20BV2%5B%22%E6%9B%B2%E7%BA%BF%E5%A4%96%E7%A7%BB%EF%BC%9A%E7%A0%B4%E5%9D%8F%E6%88%96%E5%8C%B9%E9%85%8D%E5%9C%A8%E5%8A%A8%22%5D%0A%20%20BV1%20--%3E%20P1%5B%22%E5%AF%B9%E7%97%87%EF%BC%9A%E4%BF%AE%E6%8B%9B%E8%81%98%E4%B8%8E%E5%8C%B9%E9%85%8D%E6%95%88%E7%8E%87%22%5D%0A%20%20BV2%20--%3E%20P2%5B%22%E5%AF%B9%E7%97%87%EF%BC%9A%E7%A8%B3%E5%AD%98%E9%87%8F%E5%B0%B1%E4%B8%9A%E4%B8%8E%E5%B2%97%E4%BD%8D%E4%BF%9D%E5%AD%98%22%5D%0A%20%20P1%20--%3E%20LT%5B%22%E4%B8%A4%E6%A1%88%E9%83%BD%E5%88%AB%E6%BC%8F%E9%95%BF%E5%B0%BE%EF%BC%9A%E5%AD%98%E9%87%8F%E5%A0%86%E7%A7%AF%E5%9C%A8%E9%95%BF%E6%9C%9F%E5%A4%B1%E4%B8%9A%E8%80%85%22%5D%0A%20%20P2%20--%3E%20LT%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=s('<p><span class="marginnote">术语翻译：入职率 \\(f\\) 就是「一个失业者这个月找到工作的概率」，分离率 \\(s\\) 就是「一个就业者这个月丢掉工作的概率」。它们是 hazard（危险率）不是人数：\\(f=0.2\\) 不等于 20 万人，而是失业池里每 100 人每月走 20 个。</span></p><p><span class="marginnote">数字实例：设劳动力 1 亿人、\\(u=7\\%\\)，失业池约 700 万人；若 \\(f=20\\%\\)，仅流出项每月就有约 140 万人离开失业池。也就是说失业池每个月翻新一大截——水位不变，水里的人却换了好几茬，这正是「同一水位、两种经济」的含义。</span></p><p><span class="marginnote">常见误区：用「平均失业期」判断长尾。月度数据里平均失业周数可以很短，因为大量几周就找到工作的人把平均数拉低；但数某一时点的失业存量，堆在池底的往往是失业超过半年的长期失业者。平均描述流量，分布描述存量，二者经常给出相反的图景。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课只做核算与分解，不做因果：\\(s\\) 与 \\(f\\) 是均衡结果，衰退里二者同时被冲击推动，方差分解不等于结构识别。两态会计也不区分全职与工时调整，雇主先砍工时的经济体里，就业存量的波动会低估劳动力使用的波动。估算入职率所用的转阵概率受样本流失与问卷修订影响，跨期比较要先对口径。政策评估（失业保险如何改 \\(f\\)）留给下一课。</p><p>后课默认：失业率是流量上的均衡水位，读失业先问 ins 与 outs；贝弗里奇曲线的移动要翻译成 \\(s\\)、\\(f\\) 与匹配效率的哪一块在动。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>失业率是水位：\\(\\Delta u = s(1-u) - f u\\)，稳态 \\(u^{*}=s/(s+f)\\)。</li><li>美国周期波动主要由入职率驱动；大衰退叠加分离率上升。</li><li>流量账给 U–V 图装上时钟：沿曲线是 \\(f\\) 在动，外移是 \\(s\\) 或匹配在动。</li><li>长期失业堆积在存量长尾，月度流量健康不等于存量健康。</li><li>出处：Hall, NBER Macro Annual 2005；Shimer, RED 2012；Blanchard–Diamond 1989；Elsby–Hobijn–Şahin 2010；Fujita–Ramey 2009。</li></ul>',8))])}const F=l(p,[["render",u]]);export{_ as __pageData,F as default};
